INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Digitalisierung nur das Scannen von Dokumenten?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst Prozesse und Daten"}, {"text": "Ja", "correct": false, "because": "Nur ein Teilaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Digitalisierung?', 3, '[{"text": "Effizienz steigern", "correct": true, "because": "Prozesse optimieren"}, {"text": "Papier erhöhen", "correct": false, "because": "Papier wird reduziert"}, {"text": "Kosten verdoppeln", "correct": false, "because": "Kostensenkung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche betrifft Digitalisierung?', 5, '[{"text": "Geschäftsprozesse", "correct": true, "because": "Automatisierung"}, {"text": "Datenverwaltung", "correct": true, "because": "Digital gespeichert"}, {"text": "Physische Produktion", "correct": false, "because": "Indirekt betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitalisierung nutzt Technologie. b) Sie ersetzt Menschen komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Menschen bleiben wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Digitalisierung?', 4, '[{"text": "Datenformate", "correct": false, "because": "Wichtig für Verarbeitung"}, {"text": "Technologie", "correct": false, "because": "Grundlage"}, {"text": "Möbeldesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Digitalisierung nur für Firmen ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Privatbereich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug ist typisch für Digitalisierung?', 3, '[{"text": "Cloud-Speicher", "correct": true, "because": "Digitale Datenverwaltung"}, {"text": "Schreibmaschine", "correct": false, "because": "Analog"}, {"text": "Papierkorb", "correct": false, "because": "Kein Digitaltool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt Digitalisierung?', 5, '[{"text": "Schnellere Prozesse", "correct": true, "because": "Automatisierung"}, {"text": "Bessere Zugänglichkeit", "correct": true, "because": "Daten online"}, {"text": "Mehr Papier", "correct": false, "because": "Papier wird reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Digitalisierung spart Zeit. b) Sie braucht keine Technik. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Digitalisierung?', 4, '[{"text": "Software", "correct": false, "because": "Für Prozesse nötig"}, {"text": "Internet", "correct": false, "because": "Oft erforderlich"}, {"text": "Papierakten", "correct": true, "because": "Werden ersetzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Digitalisierung dasselbe wie Automatisierung?', 2, '[{"text": "Nein", "correct": true, "because": "Digitalisierung ist breiter"}, {"text": "Ja", "correct": false, "because": "Automatisierung ist Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien fördern Digitalisierung?', 4, '[{"text": "Cloud", "correct": true, "because": "Speicher und Zugriff"}, {"text": "KI", "correct": true, "because": "Datenanalyse"}, {"text": "Bleistift", "correct": false, "because": "Analog"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Digitalisierung nur Kosten spart. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Effizienz und Innovation"}, {"text": "Ja", "correct": false, "because": "Breitere Vorteile"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Digitalisierung?', 3, '[{"text": "Datenintegration", "correct": true, "because": "Zusammenhalt wichtig"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Wird reduziert"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitalisierung ersetzt Analoges. b) Sie betrifft nur IT.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Bereiche betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen hat Digitalisierung?', 5, '[{"text": "Prozessoptimierung", "correct": true, "because": "Effizienz steigt"}, {"text": "Datenverfügbarkeit", "correct": true, "because": "Schneller Zugriff"}, {"text": "Mehr Papierkram", "correct": false, "because": "Papier reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Digitalisierung unwichtig?', 3, '[{"text": "Technologie", "correct": false, "because": "Grundlage"}, {"text": "Datenformate", "correct": false, "because": "Für Zugriff nötig"}, {"text": "Schreibtischgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht Digitalisierung immer Internet?', 3, '[{"text": "Nein", "correct": true, "because": "Auch lokal möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Digitalisierung Arbeitsplätze abbaut?', 2, '[{"text": "Nein", "correct": true, "because": "Auch neue Jobs entstehen"}, {"text": "Ja", "correct": false, "because": "Nicht nur negativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für Digitalisierung zentral?', 4, '[{"text": "Digitale Daten", "correct": true, "because": "Kern der Veränderung"}, {"text": "Manuelle Abläufe", "correct": false, "because": "Werden ersetzt"}, {"text": "Physische Akten", "correct": false, "because": "Analog"}]');
